using System.Globalization;
namespace Hs.LangSense;
public sealed record TextAnalysisResult(int CharacterCount,int LetterCount,int DigitCount,int NumberCount,int WordCount,int LineCount,int WhitespaceCount,int SymbolCount,int PersianCharacterCount,int ArabicCharacterCount,int LatinCharacterCount,int PersianDigitCount,int ArabicDigitCount,int EnglishDigitCount,int EmailCount,int UrlCount,int PhoneCount,int DateCount,int NumberWordCount,bool IsMixed);
public static class TextAnalyzer { public static TextAnalysisResult Analyze(string? text){var s=text??"";return new(s.Length,s.Count(char.IsLetter),s.Count(char.IsDigit),TextExtractor.ExtractNumbers(s).Count(),s.Split((char[]?)null,StringSplitOptions.RemoveEmptyEntries).Length,s.Count(c=>c=='\n')+1,s.Count(char.IsWhiteSpace),s.Count(c=>!char.IsLetterOrDigit(c)&&!char.IsWhiteSpace(c)),s.Count(PersianText.IsPersianLetter),s.Count(PersianText.IsArabicLetter),s.Count(c=>c is >= 'A' and <= 'Z' or >= 'a' and <= 'z'),s.Count(c=>c is >= '۰' and <= '۹'),s.Count(c=>c is >= '٠' and <= '٩'),s.Count(c=>c is >= '0' and <= '9'),Patterns.Email.Extract(s).Count(),Patterns.Url.Extract(s).Count(),Patterns.Mobile.Extract(s).Count(),DateRegex(s),PersianNumberWordCount(s),LanguageAnalyzer.Analyze(s).Count>1);}
 private static int DateRegex(string s)=>System.Text.RegularExpressions.Regex.Matches(s,@"\d{4}[/-]\d{1,2}[/-]\d{1,2}").Count; private static int PersianNumberWordCount(string s)=>s.Split(' ',StringSplitOptions.RemoveEmptyEntries).Count(x=>new[]{"یک","دو","سه","چهار","پنج","شش","هفت","هشت","نه","ده","صد","هزار","میلیون"}.Contains(x)); }
public static class LanguageAnalyzer { public static IReadOnlyList<LanguageDistribution> Analyze(string? text){var s=text??"";int p=s.Count(PersianText.IsPersianLetter),a=s.Count(PersianText.IsArabicLetter),e=s.Count(c=>c is >= 'A' and <= 'Z' or >= 'a' and <= 'z'),n=s.Count(char.IsDigit);var total=Math.Max(1,p+a+e+n);return new[]{new LanguageDistribution(Language.Persian,p*100.0/total,p),new LanguageDistribution(Language.Arabic,a*100.0/total,a),new LanguageDistribution(Language.English,e*100.0/total,e),new LanguageDistribution(Language.Numeric,n*100.0/total,n)}.Where(x=>x.Characters>0).OrderByDescending(x=>x.Percentage).ToList();}public static Language Detect(string s){var a=Analyze(s);return a.Count==0?Language.Unknown:a.Count(x=>x.Percentage>10)>1?Language.Mixed:a[0].Language;}public static bool IsMixed(string s)=>Detect(s)==Language.Mixed;}
public static class PersianText { public static bool IsPersianLetter(char c)=>"اآبپتثجچحخدذرزژسشصضطظعغفقکگلمنوهیئۀة".Contains(c);public static bool IsArabicLetter(char c)=>c is >= '\u0600' and <= '\u06FF' && !IsPersianLetter(c) && char.IsLetter(c);public static string Normalize(string s)=>Normalizer.Normalize(s,new LangSenseOptions{ConvertPersianDigitsToLatin=false}); }
public static class UnicodeAnalyzer { public static IReadOnlyList<CharacterInfo> Analyze(string text)=>text.Select((c,i)=>new CharacterInfo(c.ToString(),c,$"U+{(int)c:X4}",CharUnicodeInfo.GetUnicodeCategory(c),Script(c),LanguageOf(c),char.IsLetter(c),char.IsDigit(c),char.IsWhiteSpace(c),char.IsControl(c)||c is '\u200B' or '\u200C' or '\u200D' or '\u200E' or '\u200F' or '\uFEFF',i)).ToList(); private static string Script(char c)=>c is >= '\u0600' and <= '\u06FF'?"Arabic":c is >= 'A' and <= 'z'?"Latin":"Common";private static Language LanguageOf(char c)=>PersianText.IsPersianLetter(c)?Language.Persian:c is >= '\u0600' and <= '\u06FF'?Language.Arabic:c is >= 'A' and <= 'z'?Language.English:char.IsDigit(c)?Language.Numeric:Language.Unknown;}
public static class InvisibleCharacterAnalyzer { public static IReadOnlyList<CharacterInfo> Find(string text)=>UnicodeAnalyzer.Analyze(text).Where(x=>x.IsInvisible).ToList(); }
